{
    "type": "bubble",
    "hero": {
        "type": "image",
        "url": "https://upload.cc/i1/2026/05/06/xBUZNA.png",
        "size": "full",
        "aspectRatio": "20:13",
        "aspectMode": "cover"
    },
    "body": {
        "type": "box",
        "layout": "vertical",
        "paddingAll": "lg",
        "contents": [
            {
                "type": "text",
                "text": "高強度間歇訓練 (HIIT)",
                "weight": "bold",
                "size": "xl"
            },
            {
                "type": "box",
                "layout": "vertical",
                "margin": "lg",
                "spacing": "sm",
                "contents": [
                    {
                        "type": "box",
                        "layout": "baseline",
                        "spacing": "sm",
                        "contents": [
                            {
                                "type": "text",
                                "text": "💪",
                                "color": "#aaaaaa",
                                "size": "sm",
                                "flex": 1
                            },
                            {
                                "type": "text",
                                "text": "教練：Mark",
                                "wrap": true,
                                "color": "#666666",
                                "size": "sm",
                                "flex": 5
                            }
                        ]
                    },
                    {
                        "type": "box",
                        "layout": "baseline",
                        "spacing": "sm",
                        "contents": [
                            {
                                "type": "text",
                                "text": "⏰",
                                "color": "#aaaaaa",
                                "size": "sm",
                                "flex": 1
                            },
                            {
                                "type": "text",
                                "text": "週五 19:00 - 20:00",
                                "wrap": true,
                                "color": "#666666",
                                "size": "sm",
                                "flex": 5
                            }
                        ]
                    },
                    {
                        "type": "box",
                        "layout": "baseline",
                        "spacing": "sm",
                        "contents": [
                            {
                                "type": "text",
                                "text": "🔥",
                                "color": "#aaaaaa",
                                "size": "sm",
                                "flex": 1
                            },
                            {
                                "type": "text",
                                "text": "剩餘名額：3 位",
                                "wrap": true,
                                "color": "#E53E3E",
                                "size": "sm",
                                "flex": 5,
                                "weight": "bold"
                            }
                        ]
                    }
                ]
            }
        ]
    },
    "footer": {
        "type": "box",
        "layout": "horizontal",
        "spacing": "sm",
        "paddingAll": "lg",
        "flex": 0,
        "contents": [
            {
                "type": "button",
                "style": "secondary",
                "flex": 1,
                "action": {
                    "type": "uri",
                    "label": "課程詳情",
                    "uri": "https://line.me/"
                }
            },
            {
                "type": "button",
                "style": "primary",
                "color": "#E53E3E",
                "flex": 1,
                "action": {
                    "type": "uri",
                    "label": "立即報名",
                    "uri": "https://line.me/"
                }
            }
        ]
    }
}

{
  "type": "bubble",
  "size": "mega",
  "header": {
    "type": "box",
    "layout": "vertical",
    "backgroundColor": "#1E293B",
    "paddingAll": "24px",
    "contents": [
      {
        "type": "box",
        "layout": "horizontal",
        "alignItems": "center",
        "contents": [
          {
            "type": "box",
            "layout": "vertical",
            "backgroundColor": "#FBBF24",
            "cornerRadius": "sm",
            "paddingStart": "6px",
            "paddingEnd": "6px",
            "paddingTop": "2px",
            "paddingBottom": "2px",
            "flex": 0,
            "contents": [
              {
                "type": "text",
                "text": "重要",
                "color": "#1E293B",
                "size": "xxs",
                "weight": "bold",
                "align": "center",
                "gravity": "center"
              }
            ]
          },
          {
            "type": "text",
            "text": "SERVICE NOTICE",
            "color": "#FFFFFF66",
            "size": "xxs",
            "weight": "bold",
            "margin": "md",
            "letterSpacing": "2px"
          }
        ]
      },
      {
        "type": "text",
        "text": "系統維護公告",
        "color": "#FFFFFF",
        "weight": "bold",
        "size": "xl",
        "margin": "md"
      },
      {
        "type": "text",
        "text": "System Maintenance Announcement",
        "color": "#FFFFFF66",
        "size": "xxs",
        "margin": "xs"
      }
    ]
  },
  "body": {
    "type": "box",
    "layout": "vertical",
    "paddingAll": "24px",
    "backgroundColor": "#FFFFFF",
    "contents": [
      {
        "type": "text",
        "text": "為了提升服務品質與數據安全，我們將進行例行性系統升級，期間部分功能將暫時無法使用。",
        "wrap": true,
        "size": "sm",
        "color": "#4B5563",
        "lineSpacing": "4px"
      },
      {
        "type": "box",
        "layout": "vertical",
        "backgroundColor": "#F8FAFC",
        "cornerRadius": "md",
        "paddingAll": "16px",
        "margin": "xl",
        "contents": [
          {
            "type": "box",
            "layout": "horizontal",
            "contents": [
              {
                "type": "text",
                "text": "維護時間 (Scheduled)",
                "size": "xxs",
                "color": "#94A3B8",
                "weight": "bold"
              }
            ]
          },
          {
            "text": "2025/05/10 02:00 - 05:00",
            "type": "text",
            "size": "md",
            "weight": "bold",
            "color": "#1E293B",
            "margin": "md"
          },
          {
            "type": "box",
            "layout": "vertical",
            "margin": "md",
            "contents": [
              {
                "type": "text",
                "text": "● 預計持續約 3 小時",
                "size": "xxs",
                "color": "#64748B"
              }
            ]
          }
        ]
      },
      {
        "type": "box",
        "layout": "horizontal",
        "margin": "lg",
        "contents": [
          {
            "type": "box",
            "layout": "vertical",
            "flex": 1,
            "contents": [
              {
                "type": "text",
                "text": "受影響範圍",
                "size": "xs",
                "color": "#1E293B",
                "weight": "bold"
              },
              {
                "type": "text",
                "text": "API 串接、後台管理、數據同步",
                "size": "xxs",
                "color": "#94A3B8",
                "margin": "sm",
                "wrap": true
              }
            ]
          }
        ]
      }
    ]
  },
  "footer": {
    "type": "box",
    "layout": "vertical",
    "paddingAll": "24px",
    "paddingTop": "0px",
    "contents": [
      {
        "type": "button",
        "action": {
          "type": "uri",
          "label": "查看詳細升級清单",
          "uri": "https://liming.me"
        },
        "style": "primary",
        "color": "#06C755",
        "height": "sm"
      }
    ]
  }
}

